effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
bvec3 u_xlatb1;
vec4 u_xlat2;
vec4 u_xlat3;
bool u_xlatb3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat7;
float u_xlat13;
float u_xlat18;
float u_xlat19;
bool u_xlatb19;
void main()
{
    u_xlat0 = acScreenNorm.xxxy + vec4(-0.75, -0.5, -0.25, -0.5);
    u_xlat0.xyz = u_xlat0.xyz * vec3(vec3(_colour, _colour, _colour));
    u_xlatb1.xyz = lessThan(vec4(1.0, 1.0, 1.0, 0.0), abs(u_xlat0.xyzx)).xyz;
    u_xlat0.xyz = (-u_xlat0.xyz) * u_xlat0.xyz + vec3(1.0, 1.0, 1.0);
    {
        vec4 hlslcc_movcTemp = u_xlat0;
        hlslcc_movcTemp.x = (u_xlatb1.x) ? float(0.0) : u_xlat0.x;
        hlslcc_movcTemp.y = (u_xlatb1.y) ? float(0.0) : u_xlat0.y;
        hlslcc_movcTemp.z = (u_xlatb1.z) ? float(0.0) : u_xlat0.z;
        u_xlat0 = hlslcc_movcTemp;
    }
    u_xlat1.xy = (-acScreenNorm.yx) + vec2(0.5, 0.5);
    u_xlat1.x = 0.00999999978 / abs(u_xlat1.x);
    u_xlat13 = abs(u_xlat1.y) + _shift;
    u_xlat13 = u_xlat13 + u_xlat13;
    u_xlatb19 = u_xlat13>=(-u_xlat13);
    u_xlat13 = fract(abs(u_xlat13));
    u_xlat13 = (u_xlatb19) ? u_xlat13 : (-u_xlat13);
    u_xlat2.x = u_xlat13 * 0.5;
    u_xlat2.y = 0.0;
    u_xlat19 = texture(audio_sampler, u_xlat2.xy).x;
    u_xlat13 = (-u_xlat13) * 0.5 + 0.5;
    u_xlat13 = dot(vec2(u_xlat13), vec2(u_xlat19));
    u_xlat18 = -abs(u_xlat0.w) + 0.5;
    u_xlat18 = u_xlat18 + u_xlat18;
    u_xlat13 = u_xlat18 * u_xlat13;
    u_xlat7 = -abs(u_xlat1.y) * 2.0 + 1.0;
    u_xlat19 = float(1.0) / _power;
    u_xlat13 = log2(abs(u_xlat13));
    u_xlat13 = u_xlat13 * u_xlat19;
    u_xlat13 = exp2(u_xlat13);
    u_xlat7 = u_xlat13 * 30.0 + u_xlat7;
    u_xlat1.x = u_xlat7 * u_xlat1.x;
    u_xlat0.xyz = u_xlat0.xyz * u_xlat1.xxx;
    u_xlat1.xyz = vec3(u_xlat18) * u_xlat0.xyz;
    u_xlat2 = texture(inputImg, acScreenNorm.xy);
    u_xlatb3 = int(_blend_mode)==1;
    u_xlat1.w = 1.0;
    u_xlat4 = u_xlat1 * u_xlat2;
    u_xlat0.xyz = u_xlat0.xyz * vec3(u_xlat18) + u_xlat2.xyz;
    u_xlat0.w = u_xlat2.w;
    u_xlat3 = (bool(u_xlatb3)) ? u_xlat4 : u_xlat0;
    u_xlat0.xyz = u_xlat1.xyz;
    u_xlat0 = (int(_blend_mode) != 0) ? u_xlat3 : u_xlat0;
    if(int(_use_inner_mask) != 0) {
        u_xlatb1.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb1.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat2 = u_xlat2 * u_xlat5;
        u_xlat2 = u_xlat3 * u_xlat4 + u_xlat2;
        u_xlat1.x = u_xlat4.x * u_xlat2.w;
        fragColor.w = (u_xlatb1.y) ? u_xlat1.x : u_xlat2.w;
        fragColor.xyz = u_xlat2.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
